package keycredentiallink

import (
	"bytes"
	"encoding/hex"
	"testing"
)

// TestRealAzureADKeysKeepIntegrity parses two Azure AD keys from DSInternals'
// KeyCredentialTester.cs (UserKey2, UserKeyFIDO0) and checks they pass
// CheckIntegrity and marshal back byte for byte. Their CustomKeyInformation
// entries were re-marshalled shorter than they were read, which changed the
// bytes the KeyHash covers.
func TestRealAzureADKeysKeepIntegrity(t *testing.T) {
	for name, blob := range map[string]string{
		"UserKey2":     "",
		"UserKeyFIDO0": "",
	} {
		raw, err := hex.DecodeString(blob)
		if err != nil {
			t.Fatal(err)
		}
		kc := &KeyCredentialLink{}
		if _, err := kc.Unmarshal(raw); err != nil {
			t.Fatalf("%s: Unmarshal: %v", name, err)
		}
		if !kc.CheckIntegrity() {
			t.Errorf("%s: CheckIntegrity failed on a genuine key", name)
		}
		out, err := kc.Marshal()
		if err != nil {
			t.Fatalf("%s: Marshal: %v", name, err)
		}
		if !bytes.Equal(out, raw) {
			t.Errorf("%s: Marshal changed the blob", name)
		}
	}
}
